-- MARKET-SCOUT-1 (Rowan 2026-11-12, charter pillar reach; autonomy): the growth product manager scouts the market. Rowan: "keep improving yourself ... what are best
-- practices here, what are cutting-edge players doing, keep incorporating the new. This is what a product manager is supposed to be doing: go out and look for what the
-- latest and greatest is and incorporate it into our product."
-- What runs (fleet_tasks growth-scout, hourly at :35, SQL only; at most growth_scout_daily_requests (6) agent requests a day, each with web_search and web_fetch):
--   research  three kinds of finding, all ranked and promoted the same way: practice (best practice of leading players), competitor (market_scout_competitors: 18 tracked
--             competitors, three per area, each analysed every growth_scout_competitor_days (3) from its site, changelog and pricing) and rnd (new research and open
--             source: arXiv, GitHub, benchmarks, one per area every growth_scout_rnd_days (5)); each needs a fetched source URL.
--   scout     market_scout_areas: six areas (job search and resume, companion, research pipeline, signals and workflows, Ultrastable, personal brand), each tied to the growth
--             product and metric it serves. The oldest-due area gets one agent request: find the best practice a leading player runs, with a source URL it fetched.
--   check     a reply with no URL, no named player or thin evidence is rejected (no invented facts); a duplicate source is dropped; a stuck request is failed and retried.
--   rank      score = lift / effort x (1 + metric gap) x 1.25 for a named player; the best ranked finding of a product becomes a growth_experiments row (status proposed),
--             so growth-pm files it as GROWTH-1 with a code-task line, the code loop builds and merges it, and growth-pm measures it after 7 days (won, kept_flat, rolled_back).
--   feedback  the experiment verdict returns to the finding and to the signals table (source market-scout, read by idea-hub and the forecasts): an area whose findings win is
--             scouted daily, one with three decided and no win slows by a day (max 7). Scouted practices also enter the signals table as they are ranked.
--   clock     scout_heartbeat_age_min, scout_reply_accuracy_7d, scout_areas_overdue (each with a trigger); a stuck request self-repairs in sc-repair.
-- Off switch: ops_config growth_scout = off stops requests and promotions; the heartbeat and feedback steps keep running.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: UPDATE fleet_tasks SET enabled = 0 WHERE id = 'growth-scout'; UPDATE fleet_crons SET enabled = 0 WHERE name = 'growth-scout-hourly'; UPDATE ops_config SET value = 'off' WHERE key = 'growth_scout'

CREATE TABLE IF NOT EXISTS market_scout_areas (
  area TEXT PRIMARY KEY, product TEXT NOT NULL, metric TEXT NOT NULL, worker TEXT NOT NULL, focus TEXT NOT NULL, players TEXT NOT NULL,
  cadence_days INTEGER NOT NULL DEFAULT 1, active INTEGER NOT NULL DEFAULT 1, last_tuned_at TEXT);
CREATE TABLE IF NOT EXISTS market_scout_findings (
  id INTEGER PRIMARY KEY AUTOINCREMENT, area TEXT NOT NULL, product TEXT NOT NULL, metric TEXT NOT NULL, request_instance TEXT UNIQUE, kind TEXT NOT NULL DEFAULT 'practice',
  status TEXT NOT NULL DEFAULT 'requested', practice TEXT, players TEXT, source_url TEXT, evidence TEXT, need TEXT, title TEXT, hypothesis TEXT,
  path TEXT, anchor_line TEXT, lift_pct REAL, effort INTEGER, score REAL, experiment_id INTEGER, note TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')), updated_at TEXT, decided_at TEXT);
CREATE INDEX IF NOT EXISTS idx_market_scout_findings_status ON market_scout_findings (status, area);
CREATE TABLE IF NOT EXISTS market_scout_competitors (
  id TEXT PRIMARY KEY, area TEXT NOT NULL, name TEXT NOT NULL, url TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, last_checked TEXT, checks INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS market_scout_beats (hour TEXT PRIMARY KEY, requests INTEGER, ranked INTEGER, rejected INTEGER, promoted INTEGER);
