INSERT OR REPLACE INTO fleet_tasks (id, name, type, definition, timeout_ms, retries, version, enabled, updated_at) VALUES ('growth-scout', 'MARKET-SCOUT-1: market scouting for the growth product manager (best practices and leading players to ranked experiments)', 'workflow', '{"steps":[{"type":"sql","name":"sc-repair","db":"AUDIT","sql":"UPDATE cf_agent_requests SET status = ''failed'', error = ''MARKET-SCOUT-1: stuck over 6 hours'', finished_at = strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'') WHERE instance LIKE ''scout-%'' AND status IN (''queued'',''running'') AND created_at < strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-6 hours'')"},{"type":"sql","name":"sc-request","db":"AUDIT","sql":"INSERT INTO cf_agent_requests (requester, kind, prompt, instance, priority) SELECT ''scout:'' || a.area, ''run'', ''You are the market scout of the product manager for '' || a.product || '' ('' || a.area || ''). Your job: find what the best players do that we do not, and what current best practice says. Area: '' || a.focus || ''. Players to start from (look beyond them too): '' || a.players || ''. Use web_search and web_fetch now; prefer sources from the last 12 months (product pages, changelogs, engineering blogs, papers, pricing and onboarding flows). Our growth metric is '' || a.metric || '' = '' || COALESCE((SELECT CAST(ROUND(g.value, 3) AS TEXT) FROM v_product_growth_now g WHERE g.metric = a.metric), ''unmeasured'') || '' against a target of '' || COALESCE((SELECT CAST(g.target AS TEXT) FROM v_product_growth_now g WHERE g.metric = a.metric), ''n/a'') || ''. Practices already scouted (do not repeat): '' || COALESCE((SELECT group_concat(substr(f.title, 1, 60), ''; '') FROM (SELECT title FROM market_scout_findings WHERE area = a.area AND title IS NOT NULL ORDER BY id DESC LIMIT 8) f), ''none'') || ''. Read '' || a.worker || ''/worker.js, then pick the ONE practice a leading player runs that would most raise our metric, and that one worker.js change can adopt, reversible, no personal data, never qnfo-fleet-control, qnfo-ops, qnfo-deploy-guard, qnfo-code-orchestrator or .github. Only report what a page you fetched actually says: no source URL, no finding. Reply with ONLY these lines, each on its own line, no preface:'' || char(10) || ''PRACTICE: <what the player does, under 25 words>'' || char(10) || ''PLAYERS: <named leading players that do it>'' || char(10) || ''SOURCE: <one full https URL you fetched>'' || char(10) || ''EVIDENCE: <what that page says, under 50 words>'' || char(10) || ''NEED: <the user need it serves>'' || char(10) || ''TITLE: <our change, under 80 characters>'' || char(10) || ''LIFT: <expected percent change of our metric in 7 days, whole number>'' || char(10) || ''EFFORT: <1 to 5>'' || char(10) || ''code-task: repo=qnfo-workers path=<one worker.js>'' || char(10) || ''code-anchor: <verbatim text that occurs exactly once in that file, next to the edit>'' || char(10) || ''EDIT: <the exact change, under 120 words>'', ''scout-'' || a.area || ''-'' || strftime(''%Y%m%d'',''now'') || ''-'' || ((SELECT COUNT(*) FROM market_scout_findings f WHERE f.area = a.area AND substr(f.created_at, 1, 10) = strftime(''%Y-%m-%d'',''now'')) + 1), ''medium'' FROM v_scout_area_yield a WHERE COALESCE((SELECT value FROM ops_config WHERE key = ''growth_scout''), ''on'') <> ''off'' AND NOT EXISTS (SELECT 1 FROM market_scout_findings f WHERE f.area = a.area AND f.kind = ''practice'' AND f.status = ''requested'') AND (SELECT COUNT(*) FROM market_scout_findings f WHERE f.area = a.area AND f.kind = ''practice'' AND substr(f.created_at, 1, 10) = strftime(''%Y-%m-%d'',''now'')) < 2 AND COALESCE((SELECT MAX(f.created_at) FROM market_scout_findings f WHERE f.area = a.area AND f.kind = ''practice'' AND f.status <> ''rejected''), '''') < strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-'' || a.cadence_days || '' days'', ''+30 minutes'') AND COALESCE(a.last_try, '''') < strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-50 minutes'') AND (SELECT COUNT(*) FROM cf_agent_requests f WHERE f.instance LIKE ''scout-%'' AND substr(f.created_at, 1, 10) = strftime(''%Y-%m-%d'',''now'')) < COALESCE((SELECT CAST(value AS INTEGER) FROM ops_config WHERE key = ''growth_scout_daily_requests''), 3) ORDER BY COALESCE(a.last_good, '''') ASC LIMIT 1"},{"type":"sql","name":"sc-request-competitor","db":"AUDIT","sql":"INSERT INTO cf_agent_requests (requester, kind, prompt, instance, priority) SELECT ''scout:'' || a.area, ''run'', ''You are the competitive analyst of the product manager for '' || a.product || '' ('' || a.area || ''). Competitor: '' || c.name || '' ('' || c.url || ''). Fetch their site, changelog, pricing, docs and recent blog or release notes (last 12 months). Find what they ship or do that we do not, how they position and price it, and what users say. Our growth metric is '' || a.metric || '' = '' || COALESCE((SELECT CAST(ROUND(g.value, 3) AS TEXT) FROM v_product_growth_now g WHERE g.metric = a.metric), ''unmeasured'') || '' against a target of '' || COALESCE((SELECT CAST(g.target AS TEXT) FROM v_product_growth_now g WHERE g.metric = a.metric), ''n/a'') || ''. Use web_search and web_fetch now. Only report what a page you fetched actually says: no source URL, no finding. Read '' || a.worker || ''/worker.js, and propose the ONE change one worker.js edit can make, reversible, no personal data, never qnfo-fleet-control, qnfo-ops, qnfo-deploy-guard, qnfo-code-orchestrator or .github. Recent competitor findings (do not repeat): '' || COALESCE((SELECT group_concat(substr(f.title, 1, 60), ''; '') FROM (SELECT title FROM market_scout_findings WHERE area = a.area AND kind = ''competitor'' AND title IS NOT NULL ORDER BY id DESC LIMIT 6) f), ''none'') || ''. '' || char(10) || ''Reply with ONLY these lines, each on its own line, no preface:'' || char(10) || ''PRACTICE: <what the competitor does or shipped, under 25 words>'' || char(10) || ''PLAYERS: <the competitor name>'' || char(10) || ''SOURCE: <one full https URL you fetched>'' || char(10) || ''EVIDENCE: <what that page says, under 50 words>'' || char(10) || ''NEED: <the user need it serves and the gap against our product>'' || char(10) || ''TITLE: <our change, under 80 characters>'' || char(10) || ''LIFT: <expected percent change of our metric in 7 days, whole number>'' || char(10) || ''EFFORT: <1 to 5>'' || char(10) || ''code-task: repo=qnfo-workers path=<one worker.js>'' || char(10) || ''code-anchor: <verbatim text that occurs exactly once in that file, next to the edit>'' || char(10) || ''EDIT: <the exact change, under 120 words>'', ''scout-comp-'' || c.id || ''-'' || strftime(''%Y%m%d%H'',''now''), ''medium'' FROM market_scout_competitors c JOIN v_scout_area_yield a ON a.area = c.area WHERE c.active = 1 AND COALESCE((SELECT value FROM ops_config WHERE key = ''growth_scout''), ''on'') <> ''off'' AND (SELECT COUNT(*) FROM cf_agent_requests f WHERE f.instance LIKE ''scout-%'' AND substr(f.created_at, 1, 10) = strftime(''%Y-%m-%d'',''now'')) < COALESCE((SELECT CAST(value AS INTEGER) FROM ops_config WHERE key = ''growth_scout_daily_requests''), 6) AND COALESCE(c.last_checked, '''') < strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-'' || COALESCE((SELECT CAST(value AS INTEGER) FROM ops_config WHERE key = ''growth_scout_competitor_days''), 3) || '' days'') AND NOT EXISTS (SELECT 1 FROM market_scout_findings f WHERE f.area = c.area AND f.kind = ''competitor'' AND f.status = ''requested'') AND NOT EXISTS (SELECT 1 FROM market_scout_findings f WHERE f.kind = ''competitor'' AND f.created_at >= strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-50 minutes'')) ORDER BY COALESCE(c.last_checked, '''') ASC LIMIT 1"},{"type":"sql","name":"sc-request-rnd","db":"AUDIT","sql":"INSERT INTO cf_agent_requests (requester, kind, prompt, instance, priority) SELECT ''scout:'' || a.area, ''run'', ''You are the research and development lead of the product manager for '' || a.product || '' ('' || a.area || ''). Area: '' || a.focus || ''. Search the newest research and open source (arXiv, GitHub releases, engineering blogs, benchmarks, conference talks of the last 12 months) for a technique, model, dataset or tool that is not yet in common use here but would raise our metric, and that we could try as a small reversible experiment. Our growth metric is '' || a.metric || '' = '' || COALESCE((SELECT CAST(ROUND(g.value, 3) AS TEXT) FROM v_product_growth_now g WHERE g.metric = a.metric), ''unmeasured'') || '' against a target of '' || COALESCE((SELECT CAST(g.target AS TEXT) FROM v_product_growth_now g WHERE g.metric = a.metric), ''n/a'') || ''. Use web_search and web_fetch now. Only report what a page you fetched actually says: no source URL, no finding. Read '' || a.worker || ''/worker.js, and propose the ONE change one worker.js edit can make, reversible, no personal data, never qnfo-fleet-control, qnfo-ops, qnfo-deploy-guard, qnfo-code-orchestrator or .github. Recent R&D findings (do not repeat): '' || COALESCE((SELECT group_concat(substr(f.title, 1, 60), ''; '') FROM (SELECT title FROM market_scout_findings WHERE area = a.area AND kind = ''rnd'' AND title IS NOT NULL ORDER BY id DESC LIMIT 6) f), ''none'') || ''. '' || char(10) || ''Reply with ONLY these lines, each on its own line, no preface:'' || char(10) || ''PRACTICE: <the technique or result, under 25 words>'' || char(10) || ''PLAYERS: <authors, labs or projects behind it>'' || char(10) || ''SOURCE: <one full https URL you fetched>'' || char(10) || ''EVIDENCE: <what that page says, under 50 words>'' || char(10) || ''NEED: <the user need it serves and the gap against our product>'' || char(10) || ''TITLE: <our change, under 80 characters>'' || char(10) || ''LIFT: <expected percent change of our metric in 7 days, whole number>'' || char(10) || ''EFFORT: <1 to 5>'' || char(10) || ''code-task: repo=qnfo-workers path=<one worker.js>'' || char(10) || ''code-anchor: <verbatim text that occurs exactly once in that file, next to the edit>'' || char(10) || ''EDIT: <the exact change, under 120 words>'', ''scout-rnd-'' || a.area || ''-'' || strftime(''%Y%m%d'',''now''), ''medium'' FROM v_scout_area_yield a WHERE 1 = 1 AND COALESCE((SELECT value FROM ops_config WHERE key = ''growth_scout''), ''on'') <> ''off'' AND (SELECT COUNT(*) FROM cf_agent_requests f WHERE f.instance LIKE ''scout-%'' AND substr(f.created_at, 1, 10) = strftime(''%Y-%m-%d'',''now'')) < COALESCE((SELECT CAST(value AS INTEGER) FROM ops_config WHERE key = ''growth_scout_daily_requests''), 6) AND COALESCE((SELECT MAX(f.created_at) FROM market_scout_findings f WHERE f.area = a.area AND f.kind = ''rnd''), '''') < strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-'' || COALESCE((SELECT CAST(value AS INTEGER) FROM ops_config WHERE key = ''growth_scout_rnd_days''), 5) || '' days'') AND NOT EXISTS (SELECT 1 FROM market_scout_findings f WHERE f.area = a.area AND f.kind = ''rnd'' AND f.status = ''requested'') AND NOT EXISTS (SELECT 1 FROM market_scout_findings f WHERE f.kind = ''rnd'' AND f.created_at >= strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-50 minutes'')) ORDER BY COALESCE((SELECT MAX(f.created_at) FROM market_scout_findings f WHERE f.area = a.area AND f.kind = ''rnd''), '''') ASC LIMIT 1"},{"type":"sql","name":"sc-log","db":"AUDIT","sql":"INSERT OR IGNORE INTO market_scout_findings (area, product, metric, request_instance, kind, status, updated_at) SELECT a.area, a.product, a.metric, q.instance, CASE WHEN q.instance LIKE ''scout-comp-%'' THEN ''competitor'' WHEN q.instance LIKE ''scout-rnd-%'' THEN ''rnd'' ELSE ''practice'' END, ''requested'', strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'') FROM cf_agent_requests q JOIN market_scout_areas a ON q.requester = ''scout:'' || a.area WHERE q.instance LIKE ''scout-%''"},{"type":"sql","name":"sc-parse","db":"AUDIT","sql":"UPDATE market_scout_findings SET practice = substr(x.practice, 1, 300), players = substr(x.players, 1, 200), source_url = substr(x.source_url, 1, 400), evidence = substr(x.evidence, 1, 600), need = substr(x.need, 1, 200), title = substr(x.title, 1, 120), path = x.path, anchor_line = substr(x.anchor, 1, 300), lift_pct = MIN(MAX(COALESCE(x.lift, 5), 1), 200), effort = MIN(MAX(COALESCE(x.effort, 3), 1), 5), hypothesis = substr(x.edit_text, 1, 900), score = ROUND(MIN(MAX(COALESCE(x.lift, 5), 1), 200) / MIN(MAX(COALESCE(x.effort, 3), 1), 5) * (1 + COALESCE((SELECT g.gap FROM v_product_growth_gap g WHERE g.product = market_scout_findings.product AND g.metric = market_scout_findings.metric), 1)) * CASE WHEN length(COALESCE(x.players, '''')) > 2 THEN 1.25 ELSE 1.0 END, 3), status = CASE WHEN x.source_url LIKE ''https://%'' AND instr(substr(x.source_url, 9), ''.'') > 0 AND length(COALESCE(x.players, '''')) > 2 AND length(COALESCE(x.evidence, '''')) >= 30 AND x.title IS NOT NULL AND length(x.title) > 5 AND x.path LIKE ''%/worker.js'' AND length(COALESCE(x.anchor, '''')) > 8 AND NOT EXISTS (SELECT 1 FROM json_each(''[\"qnfo-fleet-control\",\"qnfo-ops\",\"qnfo-deploy-guard\",\"qnfo-containers-pilot\",\"qnfo-autonomy-scorer\",\"qnfo-observability\",\"qnfo-code-orchestrator\",\"qnfo-code-agent\"]'') d WHERE x.path LIKE d.value || ''/%'') THEN CASE WHEN EXISTS (SELECT 1 FROM market_scout_findings o WHERE o.source_url = x.source_url AND o.title = x.title AND o.id < market_scout_findings.id AND o.status <> ''rejected'') THEN ''rejected'' ELSE ''ranked'' END ELSE ''rejected'' END, note = CASE WHEN x.source_url LIKE ''https://%'' AND length(COALESCE(x.players, '''')) > 2 AND length(COALESCE(x.evidence, '''')) >= 30 AND x.path LIKE ''%/worker.js'' THEN note ELSE ''no checkable source, named player, evidence or one allowed worker.js with an anchor'' END, updated_at = strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'') FROM v_scout_fields x WHERE x.instance = market_scout_findings.request_instance AND market_scout_findings.status = ''requested''"},{"type":"sql","name":"sc-comp-touch","db":"AUDIT","sql":"UPDATE market_scout_competitors SET last_checked = strftime(''%Y-%m-%dT%H:%M:%SZ'',''now''), checks = checks + 1 WHERE EXISTS (SELECT 1 FROM market_scout_findings f WHERE f.kind = ''competitor'' AND f.request_instance LIKE ''scout-comp-'' || market_scout_competitors.id || ''-%'' AND f.created_at >= strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-2 hours'')) AND COALESCE(last_checked, '''') < strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-2 hours'')"},{"type":"sql","name":"sc-failed","db":"AUDIT","sql":"UPDATE market_scout_findings SET status = ''rejected'', note = ''agent request '' || COALESCE((SELECT r.status FROM cf_agent_requests r WHERE r.instance = market_scout_findings.request_instance), ''missing'') || '' without a usable reply'', updated_at = strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'') WHERE status = ''requested'' AND (EXISTS (SELECT 1 FROM cf_agent_requests r WHERE r.instance = market_scout_findings.request_instance AND r.status = ''failed'') OR created_at < strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-1 day''))"},{"type":"sql","name":"sc-signal-ranked","db":"AUDIT","sql":"INSERT OR IGNORE INTO signals (id, ts, source, source_ref, content, open_questions, evidential_weight, domain, status, created_at) SELECT ''scout-'' || f.id || ''-practice'', strftime(''%Y-%m-%dT%H:%M:%SZ'',''now''), ''market-scout'', f.source_url, CASE f.kind WHEN ''competitor'' THEN ''Competitor '' WHEN ''rnd'' THEN ''R&D: '' ELSE '''' END || f.players || '' do this: '' || f.practice || '' ('' || f.evidence || '')'', ''Does it raise '' || f.metric || '' for '' || f.product || ''?'', 0.5, f.area, ''new'', strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'') FROM market_scout_findings f WHERE f.status IN (''ranked'',''experiment'',''won'',''kept_flat'',''rolled_back'')"},{"type":"sql","name":"sc-promote","db":"AUDIT","sql":"INSERT INTO growth_experiments (kind, product, metric, request_instance, title, hypothesis, path, anchor_line, lift_pct, effort, score, status, note, updated_at) SELECT ''growth'', f.product, f.metric, ''scout-exp-'' || f.id, f.title, ''MARKET-SCOUT-1 '' || f.kind || '' finding #'' || f.id || '' ('' || f.area || ''): '' || f.players || '' do this: '' || f.practice || ''. Source: '' || f.source_url || '' . Evidence: '' || f.evidence || '' Need served: '' || COALESCE(f.need, '''') || ''. EDIT: '' || COALESCE(f.hypothesis, ''''), f.path, f.anchor_line, f.lift_pct, f.effort, f.score, ''proposed'', ''MARKET-SCOUT-1 finding #'' || f.id, strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'') FROM market_scout_findings f WHERE f.status = ''ranked'' AND COALESCE((SELECT value FROM ops_config WHERE key = ''growth_scout''), ''on'') <> ''off'' AND f.id = (SELECT x.id FROM market_scout_findings x WHERE x.product = f.product AND x.status = ''ranked'' ORDER BY x.score DESC, x.id LIMIT 1) AND NOT EXISTS (SELECT 1 FROM growth_experiments e WHERE e.product = f.product AND e.kind = ''growth'' AND e.status IN (''requested'',''proposed'',''filed'',''building'')) AND NOT EXISTS (SELECT 1 FROM growth_experiments e WHERE e.request_instance = ''scout-exp-'' || f.id) ORDER BY f.score DESC LIMIT 2"},{"type":"sql","name":"sc-promoted","db":"AUDIT","sql":"UPDATE market_scout_findings SET status = ''experiment'', experiment_id = (SELECT e.id FROM growth_experiments e WHERE e.request_instance = ''scout-exp-'' || market_scout_findings.id), updated_at = strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'') WHERE status = ''ranked'' AND EXISTS (SELECT 1 FROM growth_experiments e WHERE e.request_instance = ''scout-exp-'' || market_scout_findings.id)"},{"type":"sql","name":"sc-outcome","db":"AUDIT","sql":"UPDATE market_scout_findings SET status = CASE (SELECT e.status FROM growth_experiments e WHERE e.id = market_scout_findings.experiment_id) WHEN ''won'' THEN ''won'' WHEN ''kept_flat'' THEN ''kept_flat'' WHEN ''rolling_back'' THEN ''rolled_back'' WHEN ''rolled_back'' THEN ''rolled_back'' ELSE ''dropped'' END, decided_at = strftime(''%Y-%m-%dT%H:%M:%SZ'',''now''), updated_at = strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'') WHERE status = ''experiment'' AND (SELECT e.status FROM growth_experiments e WHERE e.id = market_scout_findings.experiment_id) IN (''won'',''kept_flat'',''rolling_back'',''rolled_back'',''abandoned'',''rejected'')"},{"type":"sql","name":"sc-signal-outcome","db":"AUDIT","sql":"INSERT OR IGNORE INTO signals (id, ts, source, source_ref, content, open_questions, evidential_weight, domain, status, created_at) SELECT ''scout-'' || f.id || ''-'' || f.status, strftime(''%Y-%m-%dT%H:%M:%SZ'',''now''), ''market-scout'', f.source_url, ''Adopting '' || f.players || ''''''s practice ('' || f.practice || '') ended '' || f.status || '' on '' || f.metric || '' for '' || f.product, ''Why did it '' || CASE f.status WHEN ''won'' THEN ''work'' ELSE ''not move the metric'' END || ''?'', CASE f.status WHEN ''won'' THEN 0.8 WHEN ''kept_flat'' THEN 0.4 ELSE 0.2 END, f.area, ''new'', strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'') FROM market_scout_findings f WHERE f.status IN (''won'',''kept_flat'',''rolled_back'')"},{"type":"sql","name":"sc-tune","db":"AUDIT","sql":"UPDATE market_scout_areas SET cadence_days = (SELECT CASE WHEN y.wins >= 1 THEN 1 WHEN y.decided >= 3 THEN MIN(market_scout_areas.cadence_days + 1, 7) ELSE market_scout_areas.cadence_days END FROM v_scout_area_yield y WHERE y.area = market_scout_areas.area), last_tuned_at = strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'') WHERE active = 1 AND cadence_days <> (SELECT CASE WHEN y.wins >= 1 THEN 1 WHEN y.decided >= 3 THEN MIN(market_scout_areas.cadence_days + 1, 7) ELSE market_scout_areas.cadence_days END FROM v_scout_area_yield y WHERE y.area = market_scout_areas.area) AND COALESCE(last_tuned_at, '''') < strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-1 day'')"},{"type":"sql","name":"sc-beat","db":"AUDIT","sql":"INSERT OR REPLACE INTO market_scout_beats (hour, requests, ranked, rejected, promoted) SELECT strftime(''%Y-%m-%dT%H:00:00Z'',''now''), (SELECT COUNT(*) FROM market_scout_findings WHERE created_at >= strftime(''%Y-%m-%dT%H:00:00Z'',''now'')), (SELECT COUNT(*) FROM market_scout_findings WHERE status IN (''ranked'',''experiment'',''won'',''kept_flat'',''rolled_back'') AND updated_at >= strftime(''%Y-%m-%dT%H:00:00Z'',''now'')), (SELECT COUNT(*) FROM market_scout_findings WHERE status = ''rejected'' AND updated_at >= strftime(''%Y-%m-%dT%H:00:00Z'',''now'')), (SELECT COUNT(*) FROM market_scout_findings WHERE status = ''experiment'' AND updated_at >= strftime(''%Y-%m-%dT%H:00:00Z'',''now''))"},{"type":"sql","name":"sc-m-scout_heartbeat_age_min","db":"AUDIT","sql":"UPDATE metric_registry SET last_value = CAST((SELECT CAST((julianday(''now'') - julianday(MAX(hour))) * 1440 AS INTEGER) FROM market_scout_beats) AS TEXT), last_refreshed = strftime(''%Y-%m-%dT%H:%M:%SZ'',''now''), state = ''MEASURED'' WHERE metric = ''scout_heartbeat_age_min''"},{"type":"sql","name":"sc-m-scout_reply_accuracy_7d","db":"AUDIT","sql":"UPDATE metric_registry SET last_value = CAST((SELECT COALESCE(ROUND(1.0 * SUM(status <> ''rejected'') / NULLIF(COUNT(*), 0), 3), 1.0) FROM market_scout_findings WHERE created_at >= strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-7 days'') AND status <> ''requested'') AS TEXT), last_refreshed = strftime(''%Y-%m-%dT%H:%M:%SZ'',''now''), state = ''MEASURED'' WHERE metric = ''scout_reply_accuracy_7d''"},{"type":"sql","name":"sc-m-scout_competitors_unchecked","db":"AUDIT","sql":"UPDATE metric_registry SET last_value = CAST((SELECT COUNT(*) FROM market_scout_competitors WHERE active = 1 AND COALESCE(last_checked, '''') < strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-14 days'') AND COALESCE((SELECT MIN(hour) FROM market_scout_beats), strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'')) < strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-14 days'')) AS TEXT), last_refreshed = strftime(''%Y-%m-%dT%H:%M:%SZ'',''now''), state = ''MEASURED'' WHERE metric = ''scout_competitors_unchecked''"},{"type":"sql","name":"sc-m-scout_areas_overdue","db":"AUDIT","sql":"UPDATE metric_registry SET last_value = CAST((SELECT COUNT(*) FROM v_scout_overdue) AS TEXT), last_refreshed = strftime(''%Y-%m-%dT%H:%M:%SZ'',''now''), state = ''MEASURED'' WHERE metric = ''scout_areas_overdue''"},{"type":"sql","name":"sc-brief","db":"AUDIT","sql":"INSERT OR REPLACE INTO persona_briefs (tick, persona_key, level, scope, verdict, decision, summary) SELECT strftime(''%Y-%m-%dT%H:00:00Z'',''now''), ''product-manager:market-scout'', ''function'', ''growth'', CASE WHEN (SELECT COUNT(*) FROM v_scout_overdue) > 0 THEN ''behind'' ELSE ''on-track'' END, ''scout leading players, rank findings into growth experiments, learn from verdicts'', (SELECT COUNT(*) FROM market_scout_findings WHERE status = ''ranked'') || '' ranked, '' || (SELECT COUNT(*) FROM market_scout_findings WHERE status = ''experiment'') || '' building or measuring, '' || (SELECT COUNT(*) FROM market_scout_findings WHERE status = ''won'') || '' won, '' || (SELECT COUNT(*) FROM market_scout_findings WHERE status = ''rejected'') || '' rejected for no checkable source.''"}]}', 60000, 1, 1, 1, strftime('%Y-%m-%dT%H:%M:%SZ','now'));
INSERT OR REPLACE INTO fleet_crons (name, cron_expr, task_id, enabled, timezone, updated_at) VALUES ('growth-scout-hourly', '35 * * * *', 'growth-scout', 1, 'UTC', strftime('%Y-%m-%dT%H:%M:%SZ','now'));
